// ClipShelf · 捕获层
//
// macOS 没有「剪贴板变更」的公开通知，只能轮询 changeCount —— 这是所有
// 剪贴板管理器的通行做法，代价极低（一次整数比较），也不需要任何权限。
//
// privacy 是这里的重点：
//   · 内容被标记为 Concealed / Transient / AutoGenerated 的，一律不收
//     （1Password、Bitwarden 等密码管理器都会打这个标记）
//   · 前台是密码管理器 App 时，跳过
//   · 自己写回剪贴板的那一下，用 changeCount 精确跳过，不产生回环

import AppKit
import CryptoKit

struct Capture {
    var kind: ClipKind
    var content: String
    var preview: String
    var bytes: Int
    var digest: String
}

final class ClipboardCapture {
    static let maxTextBytes = 2 * 1024 * 1024
    static let maxImageBytes = 8 * 1024 * 1024

    private let store: Store
    private var timer: Timer?
    private var lastChangeCount = -1
    private var expectedChangeCount: Int?

    /// 每收到一条新记录时回调（面板开着的话用来实时刷新）
    var onCapture: (() -> Void)?
    /// 被隐私规则挡下的次数，菜单里显示用
    private(set) var skippedCount = 0

    var isPaused = false

    init(store: Store) {
        self.store = store
        lastChangeCount = NSPasteboard.general.changeCount
    }

    func start(interval: TimeInterval = 0.35) {
        stop()
        let t = Timer(timeInterval: interval, repeats: true) { [weak self] _ in
            self?.poll()
        }
        t.tolerance = 0.1
        RunLoop.main.add(t, forMode: .common)
        timer = t
    }

    func stop() {
        timer?.invalidate()
        timer = nil
    }

    /// 面板粘贴时调用：告诉捕获层「接下来这次变化是我自己写的」
    func noteSelfWrite(_ changeCount: Int) {
        expectedChangeCount = changeCount
        lastChangeCount = changeCount
    }

    // MARK: 轮询

    private func poll() {
        guard !isPaused else { return }
        let pb = NSPasteboard.general
        let count = pb.changeCount
        guard count != lastChangeCount else { return }
        lastChangeCount = count

        if let expected = expectedChangeCount, count == expected {
            expectedChangeCount = nil
            return
        }

        guard let snapshot = classify(pb) else { return }
        do {
            let isNew = try store.add(
                kind: snapshot.kind,
                content: snapshot.content,
                preview: snapshot.preview,
                bytes: snapshot.bytes,
                source: Self.frontmostAppName(),
                digest: snapshot.digest
            )
            if isNew {
                store.prune()
                onCapture?()
            }
        } catch {
            NSLog("ClipShelf capture failed: \(error)")
        }
    }

    // MARK: 分类与隐私过滤

    /// 密码管理器：既看标记，也看前台应用
    private static let secretBundleIDs: Set<String> = [
        "com.1password.1password",
        "com.1password.1password7",
        "com.agilebits.onepassword7",
        "com.bitwarden.desktop",
        "com.lastpass.LastPass",
        "in.sindresorhus.KeyboardHolder",
        "com.apple.Passwords",
        "com.apple.keychainaccess",
    ]

    private static let secretTypePrefixes = [
        "com.agilebits.", "com.1password.", "com.bitwarden.",
        "org.nspasteboard.ConcealedType", "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        "com.typeit4me.", "com.apple.pasteboard.promised",
    ]

    private var frontmostBundleID: String? {
        NSWorkspace.shared.frontmostApplication?.bundleIdentifier
    }

    private static func frontmostAppName() -> String {
        guard let app = NSWorkspace.shared.frontmostApplication else { return "" }
        if app.bundleIdentifier == Bundle.main.bundleIdentifier { return "" }
        return app.localizedName ?? ""
    }

    private func isSecret(_ pb: NSPasteboard) -> Bool {
        if let bundle = frontmostBundleID {
            if Self.secretBundleIDs.contains(bundle) || bundle == Bundle.main.bundleIdentifier {
                return true
            }
        }
        for type in (pb.types ?? []) {
            for prefix in Self.secretTypePrefixes where type.rawValue.hasPrefix(prefix) {
                return true
            }
        }
        return false
    }

    private func classify(_ pb: NSPasteboard) -> Capture? {
        guard !isSecret(pb) else {
            skippedCount += 1
            return nil
        }

        // 1) 文件（Finder 里复制文件/文件夹）
        if let urls = pb.readObjects(forClasses: [NSURL.self],
                                     options: [.urlReadingFileURLsOnly: true]) as? [URL],
           !urls.isEmpty {
            let paths = urls.map { $0.path }
            let preview = urls.map { $0.lastPathComponent }.joined(separator: "  ·  ")
            let bytes = urls.reduce(0) { sum, u in
                let n = (try? u.resourceValues(forKeys: [.fileSizeKey]).fileSize) ?? 0
                return sum + n
            }
            let body = paths.joined(separator: "\n")
            guard let data = body.data(using: .utf8), data.count <= Self.maxTextBytes else { return nil }
            return Capture(kind: .files, content: body, preview: preview,
                           bytes: bytes, digest: Self.digest(data))
        }

        // 2) 文本
        if let s = pb.string(forType: .string) {
            let trimmed = s.trimmingCharacters(in: .whitespacesAndNewlines)
            if !trimmed.isEmpty {
                guard let data = s.data(using: .utf8), data.count <= Self.maxTextBytes else { return nil }
                return Capture(kind: .text, content: s, preview: Self.preview(s),
                               bytes: data.count, digest: Self.digest(data))
            }
        }

        // 3) 图片（TIFF 统一转 PNG 落盘）
        var imageData = pb.data(forType: .png)
        if imageData == nil, let tiff = pb.data(forType: .tiff) {
            imageData = Self.pngData(fromTIFF: tiff)
        }
        if let data = imageData, data.count <= Self.maxImageBytes, !data.isEmpty {
            let hash = Self.digest(data)
            let url = store.blobPath(for: hash)
            if !FileManager.default.fileExists(atPath: url.path) {
                try? data.write(to: url, options: .atomic)
            }
            let size = Self.imageSize(data) ?? .zero
            let px = "\(Int(size.width))×\(Int(size.height))"
            return Capture(kind: .image, content: url.path,
                           preview: "图片 \(px)", bytes: data.count, digest: hash)
        }

        return nil
    }

    // MARK: 工具

    private static func digest(_ data: Data) -> String {
        SHA256.hash(data: data).map { String(format: "%02x", $0) }.joined()
    }

    /// 列表里的一行摘要：折叠换行与连续空格，截断到 240 字符
    static func preview(_ s: String) -> String {
        var out = ""
        out.reserveCapacity(min(s.count, 240))
        var lastWasSpace = false
        for ch in s {
            let isSpace = ch == " " || ch == "\n" || ch == "\t" || ch == "\r"
            if isSpace {
                if !lastWasSpace { out.append(" ") }
            } else {
                out.append(ch)
            }
            lastWasSpace = isSpace
            if out.count >= 240 { break }
        }
        return out.trimmingCharacters(in: .whitespaces)
    }

    private static func pngData(fromTIFF data: Data) -> Data? {
        guard let rep = NSBitmapImageRep(data: data) else { return nil }
        return rep.representation(using: .png, properties: [:])
    }

    private static func imageSize(_ data: Data) -> NSSize? {
        guard let rep = NSBitmapImageRep(data: data) else { return nil }
        return NSSize(width: rep.pixelsWide, height: rep.pixelsHigh)
    }
}
